# Offline pip bootstrap containing the official PyPI pip 24.0 wheel.
import os
import sys
import base64
import zipfile
import io
import hashlib

WHEEL_SHA256 = "ba0d021a166865d2265246961bec0152ff124de910c5cc39f1156ce3fa7c69dc"

WHEEL_B64 = """"""

def main():
    exe_dir = os.path.dirname(os.path.abspath(sys.executable))
    sp_dir = os.path.join(exe_dir, 'Lib', 'site-packages')
    os.makedirs(sp_dir, exist_ok=True)
    
    raw = base64.b64decode(WHEEL_B64)
    actual_hash = hashlib.sha256(raw).hexdigest()
    if actual_hash != WHEEL_SHA256:
        raise RuntimeError('embedded pip wheel SHA-256 mismatch')
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        zf.extractall(sp_dir)
    print('pip 24.0 bootstrap complete in:', sp_dir)

if __name__ == '__main__':
    main()
